// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { SideNav } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Navigation/SideNav)

figma.connect(SideNav, FIGMA_NODE_URL, {
  props: {
    collapsed: figma.boolean('collapsed'),
    defaultCollapsed: figma.boolean('defaultCollapsed'),
  },
  example: ({ collapsed, defaultCollapsed }) => (
    <SideNav collapsed={collapsed} defaultCollapsed={defaultCollapsed}></SideNav>
  ),
});
